//! The registry of every `ESCUREL_*` variable the workspace reads, and the ONE source of the operator
//! environment table (`docs/deploy/env.md`, generated by `escurel-server --print-config-keys`).
//!
//! `tests/suite/config_keys.rs` fails when a key read in the sources is missing here, when a key here is
//! not read anywhere, when the committed table is stale, and when an operator document names a variable
//! that does not exist. Add the key HERE when you add the `env.get(..)` / `std::env::var(..)` call.

/// One documented variable. `name` ending in `<N>` / `<NAME>` is a family (a numbered or named series).
#[derive(Debug, Clone, Copy)]
pub struct ConfigKey {
    pub name: &'static str,
    /// Free text naming who reads it (`Server`, `Runner`, `Server / Runner`, ...).
    pub component: &'static str,
    pub default: &'static str,
    pub doc: &'static str,
}

