/// The group order of the rendered table.
const GROUPS: &[(&str, &str)] = &[
    ("Server", "escurel-server"),
    ("Server / Runner", "read by both the server and the runner"),
    ("Server / Runner / Loader", "read by several binaries"),
    ("Runner", "escurel-runner (the agent runner)"),
    ("Cli", "the `escurel` CLI"),
    ("Harness", "set by the runner for a harness subprocess"),
    (
        "Tooling",
        "scripts, compose and examples (not read by the gateway)",
    ),
    ("TestOnly", "test knobs: never set in a deployment"),
];

/// The operator environment table as markdown: what `docs/deploy/env.md` holds, byte for byte.
#[must_use]
pub fn render_markdown() -> String {
    let mut out = String::from(
        "# Environment variables\n\n\
         <!-- GENERATED by `escurel-server --print-config-keys` from `crates/escurel-server/src/config_keys.rs`.\n     \
         Do not edit by hand: change the registry, then `escurel-server --print-config-keys > docs/deploy/env.md`.\n     \
         `crates/escurel-server/tests/suite/config_keys.rs` fails when this file is stale. -->\n\n\
         Every variable the binaries read. Env overrides the TOML base file at `$ESCUREL_CONFIG`.\n",
    );
    for (group, blurb) in GROUPS {
        let keys: Vec<&ConfigKey> = CONFIG_KEYS
            .iter()
            .filter(|k| k.component == *group)
            .collect();
        if keys.is_empty() {
            continue;
        }
        out.push_str(&format!(
            "\n## {group}\n\n{blurb}.\n\n| var | default | meaning |\n|---|---|---|\n"
        ));
        for k in keys {
            out.push_str(&format!(
                "| `{}` | {} | {} |\n",
                k.name,
                cell(k.default),
                cell(k.doc)
            ));
        }
    }
    out
}

fn cell(s: &str) -> String {
    s.replace('|', "\\|").replace('\n', " ")
}
